/* -----------------------------------------------------------------------
 * test_screen_saver.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tony's display/UI subsystem (best-ui), with an AI coding assistant.
 * BJT2 Sound Modulating Toy — Frog-Tongue Screen Saver Unit Tests
 *
 * Covers screen_saver.c using the Unity test framework.
 * No hardware required — runs on any host PC via CMake.
 *
 * The rectangles ss_frame() returns are painted into a 240 x 320 array
 * of RGB565 colours, the same way the panel would paint them, so a test
 * can look at the picture: is the tongue out at the right time, is the
 * closed face back exactly after a whole cycle, does any step touch the
 * SD BUSY tag's corner.
 *
 * Test groups:
 *   Group A — When it opens and closes: 30 s, input, "not allowed",
 *             the tick wrap, a wake in the middle of a cycle
 *   Group B — What it paints: inside the panel, even pixel counts, the
 *             per-frame budget, the 4 s cycle, back to the closed face,
 *             the tag's corner, the pace after a stall
 *   Group C — NULL safety
 * ----------------------------------------------------------------------- */

#include "unity.h"
#include <stdio.h>
#include <string.h>
#include "screen_saver.h"

void setUp(void)   {}
void tearDown(void) {}

#define T0          5000U               /* the last input, in most tests */
#define FRAMES_PER_CYCLE (SS_CYCLE_MS / SS_FRAME_MS)   /* 100 */

/* Shared instances reused across tests */
static screen_saver_t ss;
static ss_rect_t      rects[SS_MAX_RECTS];
static uint16_t       panel[SS_PANEL_H][SS_PANEL_W];    /* what the panel would show */
static uint16_t       closed_face[SS_PANEL_H][SS_PANEL_W];
static char           msg[96];

/* Helper — paint n rects into the panel, in order, as the firmware does */
static void paint(uint8_t n)
{
    for (uint8_t i = 0U; i < n; i++) {
        for (uint32_t y = rects[i].y; y < (uint32_t)rects[i].y + rects[i].h; y++) {
            for (uint32_t x = rects[i].x; x < (uint32_t)rects[i].x + rects[i].w; x++) {
                panel[y][x] = rects[i].colour;
            }
        }
    }
}

/* Helper — a saver opened at T0 + SS_IDLE_MS with its first (whole) frame
 * painted; returns that time */
static uint32_t open_and_paint_face(void)
{
    uint32_t t = T0 + SS_IDLE_MS;

    ss_init(&ss, T0);
    TEST_ASSERT_TRUE(ss_update(&ss, t, true));
    memset(panel, 0xAA, sizeof(panel));              /* not a colour the saver uses */
    paint(ss_frame(&ss, t, rects, SS_MAX_RECTS));
    return t;
}

/* Helper — how many pixels of the panel have this colour */
static uint32_t count_colour(uint16_t colour)
{
    uint32_t n = 0U;
    for (uint32_t y = 0U; y < SS_PANEL_H; y++) {
        for (uint32_t x = 0U; x < SS_PANEL_W; x++) {
            if (panel[y][x] == colour) {
                n++;
            }
        }
    }
    return n;
}

/* Helper — the lowest row that has this colour, or -1 */
static int lowest_row_of(uint16_t colour)
{
    for (int y = (int)SS_PANEL_H - 1; y >= 0; y--) {
        for (uint32_t x = 0U; x < SS_PANEL_W; x++) {
            if (panel[y][x] == colour) {
                return y;
            }
        }
    }
    return -1;
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP A — When it opens and closes
 * ═══════════════════════════════════════════════════════════════════════ */

void test_A01_it_opens_after_30_000_ms_without_input(void)
{
    ss_init(&ss, T0);
    TEST_ASSERT_TRUE(ss_update(&ss, T0 + SS_IDLE_MS, true));
    TEST_ASSERT_TRUE(ss_showing(&ss));
    TEST_ASSERT_TRUE(ss_opening(&ss));              /* its first frame paints the whole face */
    TEST_ASSERT_FALSE(ss_update(&ss, T0 + SS_IDLE_MS + 10U, true));   /* opens once */
}

void test_A02_it_does_not_open_at_29_999_ms(void)
{
    ss_init(&ss, T0);
    TEST_ASSERT_FALSE(ss_update(&ss, T0 + SS_IDLE_MS - 1U, true));
    TEST_ASSERT_FALSE(ss_showing(&ss));
    TEST_ASSERT_EQUAL_UINT8(0U, ss_frame(&ss, T0 + SS_IDLE_MS - 1U, rects, SS_MAX_RECTS));
}

void test_A03_an_input_starts_the_30_s_again(void)
{
    ss_init(&ss, T0);
    TEST_ASSERT_FALSE(ss_input(&ss, T0 + 20000U));  /* not showing: it only restarts the count */
    TEST_ASSERT_FALSE(ss_update(&ss, T0 + SS_IDLE_MS, true));
    TEST_ASSERT_FALSE(ss_update(&ss, T0 + 20000U + SS_IDLE_MS - 1U, true));
    TEST_ASSERT_TRUE(ss_update(&ss, T0 + 20000U + SS_IDLE_MS, true));
}

void test_A04_an_input_while_it_shows_only_wakes_the_screen(void)
{
    uint32_t t = open_and_paint_face();

    TEST_ASSERT_TRUE(ss_input(&ss, t + 5000U));     /* it was showing: this input only wakes */
    TEST_ASSERT_FALSE(ss_showing(&ss));
    TEST_ASSERT_EQUAL_UINT8(0U, ss_frame(&ss, t + 5040U, rects, SS_MAX_RECTS));
    TEST_ASSERT_FALSE(ss_input(&ss, t + 5100U));    /* the next input is an ordinary one */
    TEST_ASSERT_TRUE(ss_update(&ss, t + 5100U + SS_IDLE_MS, true));
}

void test_A05_not_allowed_holds_the_timer(void)
{
    /* Recording, preparing, a pop-up, the fault or debug screen: the 30 s
     * start again on every pass while one of them holds */
    ss_init(&ss, T0);
    for (uint32_t t = T0; t <= T0 + 60000U; t += 1000U) {
        TEST_ASSERT_FALSE(ss_update(&ss, t, false));
    }
    TEST_ASSERT_FALSE(ss_update(&ss, T0 + 60000U + SS_IDLE_MS - 1U, true));
    TEST_ASSERT_TRUE(ss_update(&ss, T0 + 60000U + SS_IDLE_MS, true));
}

void test_A06_not_allowed_closes_it(void)
{
    /* A fault or a pop-up arrives while it shows: it closes at once */
    uint32_t t = open_and_paint_face();

    TEST_ASSERT_FALSE(ss_update(&ss, t + 100U, false));
    TEST_ASSERT_FALSE(ss_showing(&ss));
    TEST_ASSERT_FALSE(ss_update(&ss, t + 100U + SS_IDLE_MS - 1U, true));   /* and the 30 s start again */
}

void test_A07_it_may_open_on_every_screen_but_fault_and_debug(void)
{
    for (int sc = 0; sc < (int)UI_SCREEN_COUNT; sc++) {
        for (int bits = 0; bits < 8; bits++) {
            bool popup     = (bits & 1) != 0;
            bool recording = (bits & 2) != 0;
            bool preparing = (bits & 4) != 0;
            bool want = (sc != (int)UI_SCREEN_FAULT) && (sc != (int)UI_SCREEN_DEBUG) &&
                        !popup && !recording && !preparing;
            snprintf(msg, sizeof(msg), "screen %d popup %d rec %d prep %d", sc, (int)popup,
                     (int)recording, (int)preparing);
            TEST_ASSERT_EQUAL_INT_MESSAGE(want, ss_allowed((ui_screen_t)sc, popup, recording, preparing), msg);
        }
    }
}

void test_A08_it_works_across_the_tick_wrap(void)
{
    /* The last input 10 s before the 32-bit tick count wraps */
    const uint32_t t0 = 0xFFFFFFFFU - 9999U;
    const uint32_t opens = t0 + SS_IDLE_MS;          /* wraps to 20 000 */

    ss_init(&ss, t0);
    TEST_ASSERT_FALSE(ss_update(&ss, 0xFFFFFFFFU, true));
    TEST_ASSERT_FALSE(ss_update(&ss, opens - 1U, true));
    TEST_ASSERT_TRUE(ss_update(&ss, opens, true));
    TEST_ASSERT_NOT_EQUAL(0, ss_frame(&ss, opens, rects, SS_MAX_RECTS));   /* the face */

    /* Frames keep coming every 40 ms on the far side of the wrap: the
     * first mouth step after the 2 s closed */
    uint8_t first_paint_frame = 0U;
    for (uint32_t k = 1U; k <= FRAMES_PER_CYCLE && first_paint_frame == 0U; k++) {
        if (ss_frame(&ss, opens + k * SS_FRAME_MS, rects, SS_MAX_RECTS) > 0U) {
            first_paint_frame = (uint8_t)k;
        }
    }
    TEST_ASSERT_EQUAL_UINT8(SS_CLOSED_FRAMES + 1U, first_paint_frame);
}

void test_A09_a_wake_mid_cycle_then_the_next_opening_starts_afresh(void)
{
    /* A touch while the tongue is out closes the saver at once; 30 s later
     * it opens again with the whole face, and its 4 s cycle starts from
     * the beginning (2 s with the mouth shut), not where the last one was */
    uint32_t t = open_and_paint_face();
    uint32_t first_mouth_frame = 0U;

    /* 50 closed, 3 mouth-opening and 3 tongue-out frames: the tongue is half out */
    for (uint32_t k = 1U; k <= 56U; k++) {
        (void)ss_frame(&ss, t + k * SS_FRAME_MS, rects, SS_MAX_RECTS);
    }
    TEST_ASSERT_EQUAL_INT(SS_TONGUE_OUT, ss.state);
    TEST_ASSERT_TRUE(ss_input(&ss, t + 2250U));     /* it was showing: this input only wakes */

    uint32_t t2 = t + 2250U + SS_IDLE_MS;
    TEST_ASSERT_TRUE(ss_update(&ss, t2, true));
    TEST_ASSERT_TRUE(ss_opening(&ss));
    TEST_ASSERT_NOT_EQUAL(0, ss_frame(&ss, t2, rects, SS_MAX_RECTS));    /* the whole face again */
    for (uint32_t k = 1U; k <= FRAMES_PER_CYCLE && first_mouth_frame == 0U; k++) {
        if (ss_frame(&ss, t2 + k * SS_FRAME_MS, rects, SS_MAX_RECTS) > 0U) {
            first_mouth_frame = k;
        }
    }
    TEST_ASSERT_EQUAL_UINT32(SS_CLOSED_FRAMES + 1U, first_mouth_frame);
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP B — What it paints
 * ═══════════════════════════════════════════════════════════════════════ */

/* Helper — run cycles x 100 frames after the face, checking each frame
 * with check(n, frame) */
typedef void (*frame_check_t)(uint8_t n, uint32_t frame);

static void run_frames(uint32_t cycles, frame_check_t check)
{
    uint32_t t = open_and_paint_face();
    for (uint32_t k = 1U; k <= cycles * FRAMES_PER_CYCLE; k++) {
        uint8_t n = ss_frame(&ss, t + k * SS_FRAME_MS, rects, SS_MAX_RECTS);
        if (check != NULL) {
            check(n, k);
        }
        paint(n);
    }
}

static void check_inside(uint8_t n, uint32_t frame)
{
    for (uint8_t i = 0U; i < n; i++) {
        snprintf(msg, sizeof(msg), "frame %lu rect %u", (unsigned long)frame, (unsigned)i);
        TEST_ASSERT_TRUE_MESSAGE(rects[i].w > 0U && rects[i].h > 0U, msg);
        TEST_ASSERT_TRUE_MESSAGE((uint32_t)rects[i].x + rects[i].w <= SS_PANEL_W, msg);
        TEST_ASSERT_TRUE_MESSAGE((uint32_t)rects[i].y + rects[i].h <= SS_PANEL_H, msg);
    }
}

static void check_even_or_big(uint8_t n, uint32_t frame)
{
    for (uint8_t i = 0U; i < n; i++) {
        uint32_t px = (uint32_t)rects[i].w * rects[i].h;
        snprintf(msg, sizeof(msg), "frame %lu rect %u: %lu px", (unsigned long)frame, (unsigned)i,
                 (unsigned long)px);
        TEST_ASSERT_TRUE_MESSAGE((px % 2U) == 0U || px >= 250U, msg);
    }
}

static void check_budget(uint8_t n, uint32_t frame)
{
    uint32_t px = 0U;
    for (uint8_t i = 0U; i < n; i++) {
        px += (uint32_t)rects[i].w * rects[i].h;
    }
    snprintf(msg, sizeof(msg), "frame %lu: %u rects, %lu px", (unsigned long)frame, (unsigned)n,
             (unsigned long)px);
    TEST_ASSERT_TRUE_MESSAGE(n < SS_MAX_RECTS, msg);    /* at the cap, add() may have dropped some */
    TEST_ASSERT_TRUE_MESSAGE(px <= SS_FRAME_PX_MAX, msg);
}

static void check_clear_of_tag(uint8_t n, uint32_t frame)
{
    ss_rect_t tag;
    ss_tag_rect(&tag);
    for (uint8_t i = 0U; i < n; i++) {
        bool apart = (uint32_t)rects[i].x >= (uint32_t)tag.x + tag.w ||
                     (uint32_t)tag.x >= (uint32_t)rects[i].x + rects[i].w ||
                     (uint32_t)rects[i].y >= (uint32_t)tag.y + tag.h ||
                     (uint32_t)tag.y >= (uint32_t)rects[i].y + rects[i].h;
        snprintf(msg, sizeof(msg), "frame %lu rect %u", (unsigned long)frame, (unsigned)i);
        TEST_ASSERT_TRUE_MESSAGE(apart, msg);
    }
}

void test_B01_every_rect_is_inside_the_panel(void)
{
    uint32_t t = T0 + SS_IDLE_MS;
    ss_init(&ss, T0);
    (void)ss_update(&ss, t, true);
    check_inside(ss_frame(&ss, t, rects, SS_MAX_RECTS), 0U);   /* the face */
    run_frames(2U, check_inside);
}

void test_B02_every_rect_has_an_even_pixel_count_or_at_least_250(void)
{
    /* The display driver garbles a coloured box with an odd pixel count
     * under 250 (tony_ui.c, EVEN_OR_BIG) */
    uint32_t t = T0 + SS_IDLE_MS;
    ss_init(&ss, T0);
    (void)ss_update(&ss, t, true);
    check_even_or_big(ss_frame(&ss, t, rects, SS_MAX_RECTS), 0U);
    run_frames(2U, check_even_or_big);
}

void test_B03_every_frame_keeps_to_its_budget(void)
{
    /* Fewer than SS_MAX_RECTS rects in every frame, the face included
     * (add() drops a rect past the cap without a word, so a frame that
     * reaches the cap may have lost some); after the face at most
     * SS_FRAME_PX_MAX pixels (at most about 11 ms of SPI; the real steps
     * paint at most 3424 px, about 6 ms), so a step never holds up
     * TonyTask's input scan for long */
    uint32_t t = T0 + SS_IDLE_MS;
    ss_init(&ss, T0);
    (void)ss_update(&ss, t, true);
    TEST_ASSERT_LESS_THAN_UINT(SS_MAX_RECTS, ss_frame(&ss, t, rects, SS_MAX_RECTS));
    run_frames(2U, check_budget);
}

void test_B04_the_face_covers_the_whole_panel(void)
{
    (void)open_and_paint_face();
    TEST_ASSERT_EQUAL_UINT32(0U, count_colour(0xAAAAU));            /* every pixel painted */
    TEST_ASSERT_TRUE(count_colour(SS_RGB_LIP) > 0U);                /* the smile */
    TEST_ASSERT_EQUAL_UINT32(0U, count_colour(SS_RGB_TONGUE));      /* mouth shut */
    TEST_ASSERT_EQUAL_UINT32(0U, count_colour(SS_RGB_MOUTH));
}

void test_B05_the_mouth_opens_after_2_s_and_the_tongue_reaches_96_px(void)
{
    uint32_t t = open_and_paint_face();
    int      lowest_tongue = -1;
    uint32_t first_mouth_frame = 0U;

    for (uint32_t k = 1U; k <= FRAMES_PER_CYCLE; k++) {
        uint8_t n = ss_frame(&ss, t + k * SS_FRAME_MS, rects, SS_MAX_RECTS);
        paint(n);
        if (first_mouth_frame == 0U && count_colour(SS_RGB_MOUTH) > 0U) {
            first_mouth_frame = k;
        }
        int low = lowest_row_of(SS_RGB_TONGUE);
        if (low > lowest_tongue) {
            lowest_tongue = low;
        }
    }
    /* Closed for 2 s (50 frames), then the mouth opens */
    TEST_ASSERT_EQUAL_UINT32(SS_CLOSED_FRAMES + 1U, first_mouth_frame);
    /* The tongue reached 96 px below the mouth line (y 196 + 96 - 1) */
    TEST_ASSERT_EQUAL_INT(291, lowest_tongue);
}

void test_B06_one_whole_cycle_gives_back_the_closed_face_exactly(void)
{
    /* Mouth open, tongue out and back, mouth shut: after every cycle the
     * panel is the face the opening frame painted, pixel for pixel */
    uint32_t t = open_and_paint_face();
    memcpy(closed_face, panel, sizeof(panel));
    for (uint32_t k = 1U; k <= 3U * FRAMES_PER_CYCLE; k++) {
        paint(ss_frame(&ss, t + k * SS_FRAME_MS, rects, SS_MAX_RECTS));
        if ((k % FRAMES_PER_CYCLE) == 0U) {
            snprintf(msg, sizeof(msg), "after cycle %lu", (unsigned long)(k / FRAMES_PER_CYCLE));
            TEST_ASSERT_EQUAL_MEMORY_MESSAGE(closed_face, panel, sizeof(panel), msg);
        }
    }
}

void test_B07_the_sd_busy_tag_is_inside_even_and_never_painted_over(void)
{
    ss_rect_t tag;
    ss_tag_rect(&tag);
    /* x 4..67, y 4..15: 64 x 12, an even pixel count */
    TEST_ASSERT_EQUAL_UINT16(4U, tag.x);
    TEST_ASSERT_EQUAL_UINT16(4U, tag.y);
    TEST_ASSERT_EQUAL_UINT16(64U, tag.w);
    TEST_ASSERT_EQUAL_UINT16(12U, tag.h);
    TEST_ASSERT_EQUAL_UINT16(SS_RGB_TAG, tag.colour);
    TEST_ASSERT_TRUE((uint32_t)tag.x + tag.w <= SS_PANEL_W && (uint32_t)tag.y + tag.h <= SS_PANEL_H);
    TEST_ASSERT_EQUAL_UINT32(0U, ((uint32_t)tag.w * tag.h) % 2U);
    /* No animation step ever touches it ... */
    run_frames(2U, check_clear_of_tag);
    /* ... and under it the face is plain skin, so painting skin over the
     * tag when the writing stops gives the face back exactly */
    (void)open_and_paint_face();
    for (uint32_t y = tag.y; y < (uint32_t)tag.y + tag.h; y++) {
        for (uint32_t x = tag.x; x < (uint32_t)tag.x + tag.w; x++) {
            TEST_ASSERT_EQUAL_HEX16(SS_RGB_SKIN, panel[y][x]);
        }
    }
}

void test_B08_a_late_caller_gets_one_step_at_a_time(void)
{
    /* No ss_frame() call for 2.5 s after the face (TonyTask busy with a
     * long redraw): the saver skips nothing and sends no burst. It carries
     * on from the step it had reached (the first of the closed 2 s), one
     * step per 40 ms, each within the per-frame budget, and after one
     * cycle of steps the picture is the closed face again */
    uint32_t t = open_and_paint_face();
    memcpy(closed_face, panel, sizeof(panel));
    uint32_t now = t + 2500U;                        /* 2.5 s after the face; its first step was due at t + 40 */
    uint32_t frames = 0U;
    while (frames < FRAMES_PER_CYCLE) {
        uint8_t n = ss_frame(&ss, now, rects, SS_MAX_RECTS);
        check_budget(n, frames);
        paint(n);
        frames++;
        now += SS_FRAME_MS;
    }
    TEST_ASSERT_EQUAL_MEMORY(closed_face, panel, sizeof(panel));
}

/* Helper — a fingerprint of the whole picture (FNV-1a over the pixels) */
static uint32_t panel_hash(void)
{
    uint32_t h = 2166136261U;
    for (uint32_t y = 0U; y < SS_PANEL_H; y++) {
        for (uint32_t x = 0U; x < SS_PANEL_W; x++) {
            h ^= panel[y][x];
            h *= 16777619U;
        }
    }
    return h;
}

void test_B09_the_tongue_goes_back_the_way_it_came_out(void)
{
    /* The picture with the tongue L px long must be the same on the way
     * out and on the way back (L = 80, 64 ... 16), and with the tongue all
     * the way in it is the open mouth again, before the mouth shuts */
    uint32_t t = open_and_paint_face();
    uint32_t out_hash[SS_TONGUE_OUT_FRAMES + 1U];     /* [L / 16]: the picture with an L px tongue */
    uint32_t frame = 0U;

    for (uint32_t k = 1U; k <= SS_CLOSED_FRAMES + SS_MOUTH_OPENING_FRAMES; k++) {
        paint(ss_frame(&ss, t + k * SS_FRAME_MS, rects, SS_MAX_RECTS));
        frame = k;
    }
    /* The open mouth: the designed ellipse, about pi x 72 x 26 = 5881 px */
    TEST_ASSERT_UINT32_WITHIN(59U, 5881U, count_colour(SS_RGB_MOUTH));
    out_hash[0] = panel_hash();
    for (uint32_t k = 1U; k <= SS_TONGUE_OUT_FRAMES; k++) {
        frame++;
        paint(ss_frame(&ss, t + frame * SS_FRAME_MS, rects, SS_MAX_RECTS));
        out_hash[k] = panel_hash();
    }
    /* All the way out: a straight pink tongue x 104..135 from the mouth
     * line (y 196) to its 16 px tip at y 276, nothing pink beside it */
    for (uint32_t y = 196U; y < 276U; y++) {
        for (uint32_t x = 104U; x <= 135U; x++) {
            snprintf(msg, sizeof(msg), "x %lu y %lu", (unsigned long)x, (unsigned long)y);
            TEST_ASSERT_TRUE_MESSAGE(panel[y][x] == SS_RGB_TONGUE || panel[y][x] == SS_RGB_GROOVE, msg);
        }
        TEST_ASSERT_NOT_EQUAL(SS_RGB_TONGUE, panel[y][103]);
        TEST_ASSERT_NOT_EQUAL(SS_RGB_TONGUE, panel[y][136]);
    }
    for (uint32_t k = 1U; k <= SS_HOLD_FRAMES; k++) {
        frame++;
        TEST_ASSERT_EQUAL_UINT8(0U, ss_frame(&ss, t + frame * SS_FRAME_MS, rects, SS_MAX_RECTS));   /* hold */
    }
    for (uint32_t k = 1U; k <= SS_TONGUE_IN_FRAMES; k++) {
        frame++;
        paint(ss_frame(&ss, t + frame * SS_FRAME_MS, rects, SS_MAX_RECTS));
        snprintf(msg, sizeof(msg), "tongue %lu px long", (unsigned long)((SS_TONGUE_IN_FRAMES - k) * 16U));
        TEST_ASSERT_EQUAL_HEX32_MESSAGE(out_hash[SS_TONGUE_IN_FRAMES - k], panel_hash(), msg);
    }
}

void test_B10_after_a_stall_the_steps_come_40_ms_apart(void)
{
    /* TonyTask looks every 10 ms. After a 1 s stall the animation goes on
     * at its own pace (one step per 40 ms), not 4 times as fast to catch up */
    uint32_t t = open_and_paint_face();
    uint32_t steps = 0U;

    for (uint32_t dt = 1000U; dt < 1400U; dt += 10U) {
        ss_state_t state = ss.state;
        uint8_t    step  = ss.step;
        (void)ss_frame(&ss, t + dt, rects, SS_MAX_RECTS);
        if (ss.state != state || ss.step != step) {
            steps++;                                /* one step of the cycle was taken */
        }
    }
    TEST_ASSERT_EQUAL_UINT32(10U, steps);           /* 400 ms / 40 ms */
}

/* ═══════════════════════════════════════════════════════════════════════
 * GROUP C — NULL safety
 * ═══════════════════════════════════════════════════════════════════════ */

void test_C01_null_and_a_small_buffer_are_safe(void)
{
    ss_init(NULL, 0U);
    TEST_ASSERT_FALSE(ss_input(NULL, 0U));
    TEST_ASSERT_FALSE(ss_update(NULL, 0U, true));
    TEST_ASSERT_FALSE(ss_showing(NULL));
    TEST_ASSERT_FALSE(ss_opening(NULL));
    TEST_ASSERT_EQUAL_UINT8(0U, ss_frame(NULL, 0U, rects, SS_MAX_RECTS));
    ss_tag_rect(NULL);

    ss_init(&ss, T0);
    (void)ss_update(&ss, T0 + SS_IDLE_MS, true);
    TEST_ASSERT_EQUAL_UINT8(0U, ss_frame(&ss, T0 + SS_IDLE_MS, NULL, SS_MAX_RECTS));
    TEST_ASSERT_EQUAL_UINT8(0U, ss_frame(&ss, T0 + SS_IDLE_MS, rects, SS_MAX_RECTS - 1U));
    TEST_ASSERT_TRUE(ss_opening(&ss));              /* nothing was painted: the face is still due */
}

/* ═══════════════════════════════════════════════════════════════════════
 * TEST RUNNER
 * ═══════════════════════════════════════════════════════════════════════ */

int main(void)
{
    UNITY_BEGIN();

    /* Group A — When it opens and closes */
    RUN_TEST(test_A01_it_opens_after_30_000_ms_without_input);
    RUN_TEST(test_A02_it_does_not_open_at_29_999_ms);
    RUN_TEST(test_A03_an_input_starts_the_30_s_again);
    RUN_TEST(test_A04_an_input_while_it_shows_only_wakes_the_screen);
    RUN_TEST(test_A05_not_allowed_holds_the_timer);
    RUN_TEST(test_A06_not_allowed_closes_it);
    RUN_TEST(test_A07_it_may_open_on_every_screen_but_fault_and_debug);
    RUN_TEST(test_A08_it_works_across_the_tick_wrap);
    RUN_TEST(test_A09_a_wake_mid_cycle_then_the_next_opening_starts_afresh);

    /* Group B — What it paints */
    RUN_TEST(test_B01_every_rect_is_inside_the_panel);
    RUN_TEST(test_B02_every_rect_has_an_even_pixel_count_or_at_least_250);
    RUN_TEST(test_B03_every_frame_keeps_to_its_budget);
    RUN_TEST(test_B04_the_face_covers_the_whole_panel);
    RUN_TEST(test_B05_the_mouth_opens_after_2_s_and_the_tongue_reaches_96_px);
    RUN_TEST(test_B06_one_whole_cycle_gives_back_the_closed_face_exactly);
    RUN_TEST(test_B07_the_sd_busy_tag_is_inside_even_and_never_painted_over);
    RUN_TEST(test_B08_a_late_caller_gets_one_step_at_a_time);
    RUN_TEST(test_B09_the_tongue_goes_back_the_way_it_came_out);
    RUN_TEST(test_B10_after_a_stall_the_steps_come_40_ms_apart);

    /* Group C — NULL safety */
    RUN_TEST(test_C01_null_and_a_small_buffer_are_safe);

    return UNITY_END();
}
